public class MiniPomAnalyzerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static final String POM =
            "<project>\n" +
            "  <groupId>com.example</groupId>\n" +
            "  <artifactId>my-app</artifactId>\n" +
            "  <version>1.0.0</version>\n" +
            "  <properties>\n" +
            "    <maven.compiler.release>17</maven.compiler.release>\n" +
            "    <junit.version>5.10.0</junit.version>\n" +
            "  </properties>\n" +
            "  <dependencies>\n" +
            "    <dependency>\n" +
            "      <groupId>com.fasterxml.jackson.core</groupId>\n" +
            "      <artifactId>jackson-databind</artifactId>\n" +
            "      <version>2.15.2</version>\n" +
            "    </dependency>\n" +
            "    <dependency>\n" +
            "      <groupId>org.junit.jupiter</groupId>\n" +
            "      <artifactId>junit-jupiter</artifactId>\n" +
            "      <version>${junit.version}</version>\n" +
            "      <scope>test</scope>\n" +
            "    </dependency>\n" +
            "    <dependency>\n" +
            "      <groupId>org.mockito</groupId>\n" +
            "      <artifactId>mockito-core</artifactId>\n" +
            "      <version>${mockito.version}</version>\n" +
            "      <scope>test</scope>\n" +
            "    </dependency>\n" +
            "  </dependencies>\n" +
            "</project>\n";

    static final String BARE =
            "<project>\n" +
            "  <artifactId>tiny</artifactId>\n" +
            "</project>\n";

    public static void main(String[] args) {
        java.util.Map<String, String> props = MiniPomAnalyzer.properties(POM);
        check("properties size", 2, props == null ? -1 : props.size());
        check("properties junit.version", "5.10.0", props == null ? null : props.get("junit.version"));
        check("properties maven.compiler.release", "17",
                props == null ? null : props.get("maven.compiler.release"));
        java.util.Map<String, String> none = MiniPomAnalyzer.properties(BARE);
        check("no properties block gives an empty map", 0, none == null ? -1 : none.size());
        check("dependencies with scopes and resolved versions",
                "[com.fasterxml.jackson.core:jackson-databind:2.15.2:compile, "
                        + "org.junit.jupiter:junit-jupiter:5.10.0:test, "
                        + "org.mockito:mockito-core:${mockito.version}:test]",
                String.valueOf(MiniPomAnalyzer.dependencies(POM)));
        check("a pom with no dependencies", "[]", String.valueOf(MiniPomAnalyzer.dependencies(BARE)));
        check("testScoped",
                "[org.junit.jupiter:junit-jupiter:5.10.0:test, "
                        + "org.mockito:mockito-core:${mockito.version}:test]",
                String.valueOf(MiniPomAnalyzer.testScoped(POM)));
        check("testScoped on a pom with none", "[]", String.valueOf(MiniPomAnalyzer.testScoped(BARE)));
        finish();
    }
}

