public class MiniPomAnalyzer {

    public static java.util.Map<String, String> properties(String pom) {
        java.util.Map<String, String> props = new java.util.LinkedHashMap<>();
        String block = section(pom, "properties");
        int i = 0;
        while (i < block.length()) {
            int open = block.indexOf('<', i);
            if (open < 0) {
                break;
            }
            int gt = block.indexOf('>', open);
            if (gt < 0) {
                break;
            }
            String name = block.substring(open + 1, gt);
            if (name.startsWith("/")) {
                i = gt + 1;
                continue;
            }
            String close = "</" + name + ">";
            int end = block.indexOf(close, gt);
            if (end < 0) {
                break;
            }
            props.put(name, block.substring(gt + 1, end).trim());
            i = end + close.length();
        }
        return props;
    }

    public static java.util.List<String> dependencies(String pom) {
        java.util.Map<String, String> props = properties(pom);
        java.util.List<String> result = new java.util.ArrayList<>();
        int i = 0;
        while (true) {
            int start = pom.indexOf("<dependency>", i);
            if (start < 0) {
                break;
            }
            int end = pom.indexOf("</dependency>", start);
            if (end < 0) {
                break;
            }
            String block = pom.substring(start, end);
            String scope = tagValue(block, "scope");
            if (scope.isEmpty()) {
                scope = "compile";
            }
            result.add(tagValue(block, "groupId") + ":"
                    + tagValue(block, "artifactId") + ":"
                    + resolveVersion(tagValue(block, "version"), props) + ":"
                    + scope);
            i = end + "</dependency>".length();
        }
        return result;
    }

    public static java.util.List<String> testScoped(String pom) {
        java.util.List<String> result = new java.util.ArrayList<>();
        for (String dep : dependencies(pom)) {
            if (dep.endsWith(":test")) {
                result.add(dep);
            }
        }
        return result;
    }

    private static String resolveVersion(String version, java.util.Map<String, String> props) {
        if (version.startsWith("${") && version.endsWith("}")) {
            String key = version.substring(2, version.length() - 1);
            if (props.containsKey(key)) {
                return props.get(key);
            }
        }
        return version;
    }

    private static String section(String text, String tag) {
        String open = "<" + tag + ">";
        String close = "</" + tag + ">";
        int start = text.indexOf(open);
        if (start < 0) {
            return "";
        }
        int end = text.indexOf(close, start);
        if (end < 0) {
            return "";
        }
        return text.substring(start + open.length(), end);
    }

    private static String tagValue(String text, String tag) {
        String open = "<" + tag + ">";
        int start = text.indexOf(open);
        if (start < 0) {
            return "";
        }
        int end = text.indexOf("</" + tag + ">", start);
        if (end < 0) {
            return "";
        }
        return text.substring(start + open.length(), end).trim();
    }
}
